"""Order and fill data structures for the backtesting engine."""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime
from enum import Enum


class OrderSide(str, Enum):
    BUY = "buy"
    SELL = "sell"


class OrderType(str, Enum):
    MARKET = "market"
    # Limit/stop orders can be added later


class OrderStatus(str, Enum):
    PENDING = "pending"
    FILLED = "filled"
    CANCELLED = "cancelled"
    REJECTED = "rejected"


@dataclass
class Order:
    """A market order generated by the strategy or risk engine."""

    side: OrderSide
    quantity: float
    signal_bar_index: int
    reason: str = ""
    order_type: OrderType = OrderType.MARKET
    status: OrderStatus = OrderStatus.PENDING
    created_at: datetime | None = None


@dataclass
class Fill:
    """An executed order fill."""

    order: Order
    fill_bar_index: int
    fill_date: datetime
    price: float
    quantity: float
    commission: float
    slippage_cost: float
    side: OrderSide

    @property
    def notional(self) -> float:
        return self.price * self.quantity
